// Agrupa os anúncios por página e calcula um placar de sinais de escala.
// Ajuste os limites abaixo se quiser.
const EXCLUDE = /(law|attorney|tax relief|insurance|bank|sofi|financial group|timeshare|roofing)/i;
const today = new Date();
const pages = {};

for (const it of $input.all()) {
  const a = it.json;
  if (!a.pageId) continue;
  if (EXCLUDE.test(a.pageName || '')) continue;
  if (!pages[a.pageId]) {
    pages[a.pageId] = {
      pageId: a.pageId,
      pageName: a.pageName || '',
      ads: 0,
      maxDays: 0,
      maxVariants: 1,
      prices: [],
      formats: new Set(),
      sampleTitle: a.title || '',
      sampleLink: a.linkUrl || '',
      adUrl: a.adLibraryUrl || ''
    };
  }
  const p = pages[a.pageId];
  p.ads += 1;
  if (a.startDate) {
    const d = Math.floor((today - new Date(a.startDate)) / 86400000);
    if (d > p.maxDays) p.maxDays = d;
  }
  p.maxVariants = Math.max(p.maxVariants, Number(a.collationCount) || 1);
  const text = `${a.title || ''} ${a.bodyText || ''}`;
  for (const m of text.matchAll(/\$\s?(\d{1,3}(?:\.\d{2})?)/g)) {
    const v = parseFloat(m[1]);
    if (v >= 1 && v <= 47) p.prices.push(v);
  }
  if (a.displayFormat) p.formats.add(a.displayFormat);
}

const rows = Object.values(pages).map(p => {
  let score = 0;
  if (p.ads >= 3) score += 2;
  if (p.ads >= 10) score += 1;
  if (p.maxDays >= 30) score += 2;
  if (p.maxDays >= 60) score += 1;
  if (p.maxVariants >= 3) score += 1;
  if (p.prices.length) score += 1;
  if (p.formats.size >= 2) score += 1;
  return {
    json: {
      score,
      pageName: p.pageName,
      activeAds: p.ads,
      daysRunning: p.maxDays,
      maxVariants: p.maxVariants,
      lowestPriceUsd: p.prices.length ? Math.min(...p.prices) : '',
      formats: [...p.formats].join(', '),
      sampleTitle: p.sampleTitle,
      landingPage: p.sampleLink,
      adLibraryUrl: p.adUrl,
      minedAt: today.toISOString().slice(0, 10)
    }
  };
});

rows.sort((x, y) => y.json.score - x.json.score || y.json.activeAds - x.json.activeAds);
return rows.slice(0, 15);

// Fica só com a oferta mais bem ranqueada.
const items = $input.all();
return items.length ? [items[0]] : [];

// Monta o pedido para a API do Claude.
const NICHE = 'personal finance / debt (US market)';
const offer = $('Pegar a melhor oferta').first().json;
const raw = $input.first().json || {};

let pageText = '';
if (typeof raw.data === 'string') {
  pageText = raw.data
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);
}

const prompt = [
  'You are a direct-response copywriter and market analyst.',
  'Below is data about an ad running on Meta in the US, plus text from its landing page when available.',
  'Niche: ' + NICHE + '.',
  '',
  'OFFER DATA (JSON):',
  JSON.stringify(offer),
  '',
  'LANDING PAGE TEXT (may be empty):',
  pageText || '(not available)',
  '',
  'Tasks:',
  '1. offer_analysis: promise, audience, hook_pattern, offer_structure. State only what the data supports; write "unknown" otherwise.',
  '2. product_angle: ONE original product angle for the same niche that is clearly different from this offer (different audience or mechanism). Do not copy its name, wording, claims or visuals.',
  '3. video_scripts: 3 scripts for 20-30 second vertical videos. Each has title, hook (first 3 seconds), script (voiceover and on-screen text) and cta.',
  '4. ad_texts: 3 variations with primary_text, headline (max 40 characters) and description (max 30 characters).',
  '5. compliance_notes: risks for Meta ads in this niche.',
  '',
  'Rules: write the copy in English. No income or outcome guarantees. Do not address the viewer\'s personal financial situation or attributes (no "Are you in debt?"). No fake testimonials, statistics or social proof. Include a short "educational, not financial advice" line in at least one ad text.',
  '',
  'Return ONLY valid JSON with these keys: offer_analysis {promise, audience, hook_pattern, offer_structure}, product_angle, video_scripts [{title, hook, script, cta}], ad_texts [{primary_text, headline, description}], compliance_notes [strings]. No markdown fences.'
].join('\n');

return [{
  json: {
    offer,
    requestBody: {
      model: 'claude-sonnet-5-5',
      max_tokens: 3500,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

// Transforma a resposta em linhas para a planilha.
const meta = $('Montar pedido').first().json.offer;
const resp = $input.first().json;
let text = (resp.content || []).map(c => c.text || '').join('');
text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

const base = { minedAt: meta.minedAt, offer: meta.pageName };
let data;
try {
  data = JSON.parse(text);
} catch (e) {
  return [{ json: { ...base, type: 'erro', title: 'A resposta não veio em JSON válido', body: (text || JSON.stringify(resp)).slice(0, 2000), extra: '' } }];
}

const a = data.offer_analysis || {};
const rows = [];
rows.push({ json: { ...base, type: 'analise', title: 'Promessa, público e gancho',
  body: [a.promise, a.audience, a.hook_pattern, a.offer_structure].filter(Boolean).join(' | '),
  extra: 'Ângulo original: ' + (data.product_angle || '') } });
(data.video_scripts || []).forEach(v => rows.push({ json: { ...base, type: 'video', title: v.title || '',
  body: 'GANCHO: ' + (v.hook || '') + '\n' + (v.script || ''), extra: v.cta || '' } }));
(data.ad_texts || []).forEach(t => rows.push({ json: { ...base, type: 'anuncio', title: t.headline || '',
  body: t.primary_text || '', extra: t.description || '' } }));
rows.push({ json: { ...base, type: 'conformidade', title: 'Riscos na Meta',
  body: (data.compliance_notes || []).join(' | '), extra: '' } });
return rows;
